WITH metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY device_code ORDER BY humidity ASC, id ASC) AS humidity_bucket, FIRST_VALUE(humidity, TRUE) OVER (PARTITION BY device_code ORDER BY humidity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_humidity, CORR(status_bits, temp_c) OVER (PARTITION BY device_code) AS corr_status_bits_temp_c FROM device_readings) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, humidity_bucket, corr_status_bits_temp_c, CASE WHEN device_code RLIKE '^(DV-04|DV-02)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS device_code_zone FROM metrics ORDER BY device_code DESC NULLS FIRST;
